using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Text.Json;

namespace AjMyers.Tm1.Codegen;

/// <summary>Emits Model.g.cs: an enum per CSDL enum type, a class per entity and complex type, and
/// the registry of hierarchies read by <c>@odata.type</c>, as the Java client's generated model.</summary>
public sealed class ModelEmitter
{
    public const string Header =
        "// <auto-generated>\n// Generated from spec/tm1-api.json by Tm1.Codegen: don't edit, don't commit.\n// </auto-generated>\n#nullable enable\n";

    private static readonly Dictionary<string, (string Type, bool Value)> Edm = new()
    {
        ["Edm.String"] = ("string", false),
        ["Edm.Boolean"] = ("bool", true),
        ["Edm.Byte"] = ("int", true),
        ["Edm.SByte"] = ("int", true),
        ["Edm.Int16"] = ("int", true),
        ["Edm.Int32"] = ("int", true),
        ["Edm.Int64"] = ("long", true),
        ["Edm.Single"] = ("double", true),
        ["Edm.Double"] = ("double", true),
        ["Edm.Decimal"] = ("decimal", true),
        ["Edm.Date"] = ("DateOnly", true),
        ["Edm.TimeOfDay"] = ("TimeOnly", true),
        ["Edm.DateTimeOffset"] = ("DateTimeOffset", true),
        ["Edm.Duration"] = ("TimeSpan", true),
        ["Edm.Guid"] = ("Guid", true),
        ["Edm.PrimitiveType"] = ("JsonElement", true),
    };

    private readonly Spec _spec;
    private readonly StringBuilder _out = new();

    public ModelEmitter(Spec spec) => _spec = spec;

    /// <summary>The C# type of a CSDL type, and whether it's a value type; null for streams.</summary>
    public static (string Type, bool Value)? Element(Spec spec, string typeName)
    {
        if (typeName == "Edm.Stream")
        {
            return null;
        }
        if (Edm.TryGetValue(typeName, out var edm))
        {
            return edm;
        }
        if (spec.EnumByName.TryGetValue(typeName, out var e))
        {
            return Spec.Bool(e, "flags") ? ("string", false) : (Spec.Str(e, "name")!, true);
        }
        if (spec.TypeByName.TryGetValue(typeName, out var t))
        {
            return (Spec.Str(t, "name")!, false);
        }
        return ("JsonElement", true);
    }

    /// <summary>A property's member names across a type's hierarchy, unique, root first.</summary>
    public static Dictionary<string, string> MemberNames(Spec spec, JsonElement t)
    {
        var taken = new HashSet<string> { "ETag", "Fields", "DynamicProperties" };
        var result = new Dictionary<string, string>();
        foreach (var level in spec.Chain(t))
        {
            var typeName = Spec.Str(level, "name")!;
            foreach (var p in Spec.Array(level, "properties").Concat(Spec.Array(level, "navigationProperties")))
            {
                var name = Names.Member(Spec.Str(p, "name")!);
                if (name == Spec.Str(t, "name") || name == typeName)
                {
                    name += "Value";
                }
                result[Spec.Str(p, "name")!] = Names.Unique(name, taken);
            }
        }
        return result;
    }

    public string Emit()
    {
        _out.Append(Header);
        _out.Append(
            """
            using System;
            using System.Collections.Generic;
            using System.Text.Json;
            using System.Text.Json.Serialization;
            using AjMyers.Tm1.Client.Json;
            using AjMyers.Tm1.Client.OData;

            namespace AjMyers.Tm1.Client.Model;

            """
        );
        foreach (var e in _spec.Enums)
        {
            EmitEnum(e);
        }
        foreach (var t in _spec.Types)
        {
            EmitType(t);
        }
        EmitRegistry();
        return _out.ToString();
    }

    private void Summary(string indent, string? text, JsonElement item)
    {
        var parts = new List<string>();
        if (!string.IsNullOrWhiteSpace(text))
        {
            parts.Add(Names.Doc(text.Trim()));
        }
        if (Spec.Str(item, "since") is { } since)
        {
            parts.Add($"Since TM1 schema {since}.");
        }
        if (item.TryGetProperty("deprecated", out var d) && d.ValueKind == JsonValueKind.Object)
        {
            parts.Add($"Deprecated in TM1 schema {Spec.Str(d, "version")}" + (Spec.Str(d, "reason") is { } r ? ": " + Names.Doc(r.Trim()) : "."));
        }
        if (parts.Count == 0)
        {
            return;
        }
        _out.Append(indent).Append("/// <summary>");
        _out.Append(string.Join(" ", string.Join(" ", parts).Split((char[]?)null, System.StringSplitOptions.RemoveEmptyEntries)));
        _out.Append("</summary>\n");
    }

    private void EmitEnum(JsonElement e)
    {
        var name = Spec.Str(e, "name")!;
        _out.Append('\n');
        Summary(
            "",
            (Spec.Str(e, "description") ?? $"The <c>{name}</c> enum type of the TM1 REST API.")
                + " A value this client doesn't know reads as the fallback member, which is never sent.",
            e
        );
        _out.Append($"[Tm1Enum(\"{Spec.Str(e, "qualifiedName")}\")]\n");
        _out.Append($"public enum {name}\n{{\n");
        var taken = new HashSet<string>();
        foreach (var m in Spec.Array(e, "members"))
        {
            var member = Names.Unique(Names.Member(Spec.Str(m, "name")!), taken);
            Summary("    ", Spec.Str(m, "description"), m);
            _out.Append($"    [Tm1EnumMember(\"{Spec.Str(m, "name")}\")]\n    {member},\n");
        }
        var fallback = taken.Contains("Unknown") ? "Unrecognized" : "Unknown";
        _out.Append("    /// <summary>A value this client doesn't know. It's never sent.</summary>\n");
        _out.Append($"    [Tm1EnumFallback]\n    {fallback},\n}}\n");
    }

    private void EmitType(JsonElement t)
    {
        var name = Spec.Str(t, "name")!;
        var root = _spec.Root(t);
        var baseType = _spec.Base(t);
        var entity = Spec.Str(t, "kind") == "entity";
        _out.Append('\n');
        var head = Spec.Str(t, "description") ?? $"The <c>{name}</c> {(entity ? "entity" : "complex")} type of the TM1 REST API.";
        if (baseType is not null)
        {
            head += $" A kind of <see cref=\"{Spec.Str(root, "name")}\"/>, read by <c>@odata.type</c> <c>#{Spec.Str(t, "qualifiedName")}</c>.";
        }
        if (_spec.Derived(t).Any())
        {
            head +=
                " Reads as one of "
                + string.Join(", ", _spec.Derived(t).Select(d => $"<see cref=\"{Spec.Str(d, "name")}\"/>"))
                + " by <c>@odata.type</c>, or as this type itself.";
        }
        Summary("", head + " Every property is optional: <c>$select</c> can leave any out, and navigation properties are there only when expanded.", t);
        _out.Append($"public partial class {name}{(baseType is { } b ? " : " + Spec.Str(b, "name") : "")}\n{{\n");
        var members = MemberNames(_spec, t);
        if (entity && baseType is null)
        {
            _out.Append("    /// <summary>The entity's ETag (<c>@odata.etag</c>), for <c>If-Match</c>.</summary>\n");
            _out.Append("    [JsonPropertyName(\"@odata.etag\")]\n    public string? ETag { get; init; }\n");
        }
        foreach (var p in Spec.Array(t, "properties"))
        {
            var prop = Spec.Str(p, "name")!;
            string type;
            var attributes = new List<string> { $"[JsonPropertyName(\"{prop}\")]" };
            if (p.TryGetProperty("departure", out _))
            {
                type = "JsonElement?";
            }
            else if (p.TryGetProperty("lenientDate", out _))
            {
                type = "DateTimeOffset?";
                attributes.Add("[JsonConverter(typeof(LenientDateTimeOffsetConverter))]");
            }
            else if (Element(_spec, Spec.Str(p, "type")!) is { } el)
            {
                type = Spec.Bool(p, "collection") ? $"IReadOnlyList<{el.Type}>?" : el.Type + "?";
            }
            else
            {
                continue;
            }
            var doc = Spec.Str(p, "description");
            if (p.TryGetProperty("departure", out var dep))
            {
                doc += " " + Spec.Str(dep, "note");
            }
            if (p.TryGetProperty("lenientDate", out var len))
            {
                doc += " " + Spec.Str(len, "note");
            }
            Summary("    ", doc, p);
            _out.Append("    ").Append(string.Join("\n    ", attributes)).Append('\n');
            _out.Append($"    public {type} {members[prop]} {{ get; init; }}\n");
        }
        foreach (var n in Spec.Array(t, "navigationProperties"))
        {
            var nav = Spec.Str(n, "name")!;
            if (Element(_spec, Spec.Str(n, "type")!) is not { } el)
            {
                continue;
            }
            var type = Spec.Bool(n, "collection") ? $"IReadOnlyList<{el.Type}>?" : el.Type + "?";
            Summary("    ", (Spec.Str(n, "description") ?? "") + " (When expanded.)", n);
            _out.Append($"    [JsonPropertyName(\"{nav}\")]\n    public {type} {members[nav]} {{ get; init; }}\n");
        }
        if (Spec.Bool(t, "open") && !(baseType is { } bt && Spec.Bool(bt, "open")))
        {
            _out.Append("    /// <summary>The properties <c>$metadata</c> doesn't declare, which an open type can have, such as attribute values.</summary>\n");
            _out.Append("    [JsonExtensionData]\n    public Dictionary<string, JsonElement>? DynamicProperties { get; init; }\n");
        }
        // Field constants, as the Java model's Cube.NAME: its own and its root's
        _out.Append($"    /// <summary>The properties of <c>{name}</c>, for queries and filters: <c>{name}.Fields.Name</c>.</summary>\n");
        _out.Append($"    public {(baseType is null ? "" : "new ")}static class Fields\n    {{\n");
        var fieldNames = new HashSet<string>();
        foreach (var level in _spec.Chain(t))
        {
            foreach (var p in Spec.Array(level, "properties").Concat(Spec.Array(level, "navigationProperties")))
            {
                if (Spec.Str(p, "type") == "Edm.Stream")
                {
                    continue;
                }
                var prop = Spec.Str(p, "name")!;
                var field = Names.Unique(members[prop], fieldNames);
                _out.Append($"        public static readonly ODataProperty {field} = new(\"{prop}\");\n");
            }
        }
        _out.Append("    }\n}\n");
    }

    private void EmitRegistry()
    {
        _out.Append("\n/// <summary>The hierarchies read by <c>@odata.type</c>, for the polymorphic converter.</summary>\n");
        _out.Append("internal static class Tm1ModelRegistry\n{\n");
        _out.Append(
            "    public static readonly IReadOnlyDictionary<Type, IReadOnlyDictionary<string, Type>> Hierarchies = new Dictionary<Type, IReadOnlyDictionary<string, Type>>\n    {\n"
        );
        foreach (var t in _spec.Types.Where(t => _spec.Derived(t).Any()))
        {
            _out.Append($"        [typeof({Spec.Str(t, "name")})] = new Dictionary<string, Type>\n        {{\n");
            foreach (var d in _spec.Derived(t).Append(t))
            {
                var q = Spec.Str(d, "qualifiedName")!;
                _out.Append($"            [\"{q}\"] = typeof({Spec.Str(d, "name")}),\n");
                _out.Append($"            [\"{_spec.AliasName(q)}\"] = typeof({Spec.Str(d, "name")}),\n");
            }
            _out.Append("        },\n");
        }
        _out.Append("    };\n\n");
        _out.Append("    /// <summary>The <c>@odata.type</c> each derived type is sent with.</summary>\n");
        _out.Append("    public static readonly IReadOnlyDictionary<Type, string> TypeIds = new Dictionary<Type, string>\n    {\n");
        foreach (var t in _spec.Types.Where(t => _spec.Base(t) is not null))
        {
            _out.Append($"        [typeof({Spec.Str(t, "name")})] = \"#{Spec.Str(t, "qualifiedName")}\",\n");
        }
        _out.Append("    };\n}\n");
    }
}
